<?php
declare(strict_types=1);
namespace App\Infrastructure\QuestionLearning;
use App\Application\QuestionLearning\DTO\Response\QuestionExplanationProviderResponseDto;use App\Application\QuestionLearning\Port\QuestionExplanationProviderInterface;use App\Domain\QuestionLearning\ValueObject\QuestionExplanationContext;
final class CodexQuestionExplanationProvider implements QuestionExplanationProviderInterface { public function explain(QuestionExplanationContext $context,array $schema):QuestionExplanationProviderResponseDto { $workspace='/correction-workspaces/question-explanation-'.bin2hex(random_bytes(8));if(!mkdir($workspace,0700,true)&&!is_dir($workspace))throw new \RuntimeException('Workspace indisponível.');try{file_put_contents($workspace.'/schema.json',json_encode($schema,JSON_THROW_ON_ERROR));file_put_contents($workspace.'/context.json',json_encode($context,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE));$network=(string)(getenv('EXPLANATION_CODEX_NETWORK')?:getenv('CORRECTION_CODEX_NETWORK')?:'conquistaai_public');$volume=(string)(getenv('CORRECTION_WORKSPACE_VOLUME')?:'conquistaai_correction_workspaces');$auth=(string)(getenv('CODEX_AUTH_VOLUME')?:'conquistaai_codex_auth');$prompt='Use exclusivamente context.json. Respeite safetyMode: em CONCEPTUAL_ONLY, não revele gabarito, alternativa correta ou formulação que permita inferi-los. Em POST_ANSWER, quando editorialNote existir, considere-a como ressalva editorial e explique o entendimento aplicável sem tratar a inferência como fato. Retorne somente JSON conforme schema.json.';$command=['docker','run','--rm','--network',$network,'--mount','type=volume,src='.$volume.',dst=/correction-workspaces','--mount','type=volume,src='.$auth.',dst=/root/.codex','-w',$workspace,'concursos-codex-runner','exec','--ephemeral','--ignore-user-config','--ignore-rules','--sandbox','workspace-write','--skip-git-repo-check','--cd',$workspace,'--output-schema',$workspace.'/schema.json','--output-last-message',$workspace.'/result.json',$prompt];$process=proc_open($command,[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes,$workspace);if(!is_resource($process))throw new \RuntimeException('Executor Codex indisponível.');fclose($pipes[0]);stream_set_blocking($pipes[1],false);stream_set_blocking($pipes[2],false);$timeout=max(30,(int)(getenv('EXPLANATION_CODEX_TIMEOUT')?:180));$started=microtime(true);$stderr='';$stdout='';while(($state=proc_get_status($process))['running']){if(microtime(true)-$started>$timeout){proc_terminate($process,9);throw new \RuntimeException('Tempo limite da explicação excedido.');}$stdout.=stream_get_contents($pipes[1]);$stderr.=stream_get_contents($pipes[2]);usleep(200000);}foreach([1,2] as $i){$chunk=stream_get_contents($pipes[$i]);if($i===2)$stderr.=$chunk;else $stdout.=$chunk;fclose($pipes[$i]);}$exit=proc_close($process);if($exit!==0)throw new \RuntimeException('Executor Codex não concluiu.');$payload=json_decode((string)file_get_contents($workspace.'/result.json'),true,512,JSON_THROW_ON_ERROR);if(!is_array($payload))throw new \RuntimeException('Resposta Codex inválida.');return new QuestionExplanationProviderResponseDto($payload,'codex','configured',null,(int)((microtime(true)-$started)*1000));}finally{foreach(['schema.json','context.json','result.json'] as $file)if(is_file($workspace.'/'.$file))unlink($workspace.'/'.$file);@rmdir($workspace);} } }
